mapper.select:

SELECT 

    (SELECT COUNT(*) 
       FROM TEAM1_202501F.MEMBER
    ) AS TOTAL_MEMBERS,


    (SELECT COUNT(*) 
       FROM TEAM1_202501F.MEMBER M
       JOIN TEAM1_202501F.USERS U ON M.USER_ID = U.USER_ID
      WHERE U.USER_CREATE_DATE >= ADD_MONTHS(SYSDATE, -1)
    ) AS RECENT_MEMBERS,


    (SELECT COUNT(DISTINCT R.USER_ID) 
       FROM TEAM1_202501F.RESUME R
      WHERE R.RESUME_SUBMIT_YN = 'Y'
        AND R.RESUME_DELETE_DATE IS NULL
    ) AS ACTIVE_PROFILES,

    (SELECT COUNT(DISTINCT S.USER_ID) 
       FROM TEAM1_202501F.SCRAB_USER S
      WHERE S.COMPANY_ID = #{userId}
    ) AS SCRABBED_MEMBERS
FROM DUAL;
